entries[147804] = { ["name"] = "Wild Dreamrunner", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Wild Dreamrunner.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Legionfall.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\nSell Price:\n\"Dreamrunners flit between this world and the Emerald Dream at will, reveling in their wild nature.\"\nDrop:\nDreamweaver Cache" }
entries[147805] = { ["name"] = "Valarjar Stormwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Valarjar Stormwing.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Legionfall.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\nSell Price:\n\"The beating of its wings sound like the rolling of thunder in the distance.\"\nDrop:\nValarjar Strongbox" }
entries[147806] = { ["name"] = "Cloudwing Hippogryph", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Legionfall.\nSell Price:\n\"Moreso than normal hippogryphs, the cloudwings of Azsuna prefer to nest high up in mountain caves far above the cloud line.\"\nDrop:\nFarondis Chest" }
entries[147807] = { ["name"] = "Highmountain Elderhorn", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Highmountain Elderhorn.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Legionfall.\nSell Price:\n\"The favored mount of Highmountain hunters, they can easily leap across the rushing rivers of Pinerock Basin even when saddled with a full-sized Tauren.\"\nDrop:\nHighmountain Supplies" }
