entries[147867] = { ["name"] = "Pilfered Sweeper", ["text"] = "Binds when picked up\nToy\nUse: Place your Pilfered Sweeper on the ground. It is very low on energy and won't last for long. (5 Min Cooldown)\nAvailable with the release of Legion Remix: Legionfall.\n\"Letting the wyrmtongue loose on Suramar's gilded streets was not the best idea. They thought it was great, though.\"\nSell Price:" }
